import{_ as e,o as t,c as s,a5 as l}from"./chunks/framework.CXroN2RO.js";const g=JSON.parse('{"title":"C++の言語機能を学ぶ","description":"","frontmatter":{"title":"C++の言語機能を学ぶ","study":{"source":"C++ Wiki","status":"published","summary":"C++の言語機能を「構文」ではなく「仕組みと目的」から説明する章です。各ページに必ず、C#との違い/Unity開発者が誤解しやすい点/ゲーム開発での使用例/メモリ上で起きることを含めています。","section":"learning","format":"path","domain":"languages","collection":"cpp-design","order":5}},"headers":[],"relativePath":"languages/cpp/index.md","filePath":"languages/cpp/index.md"}'),n={name:"languages/cpp/index.md"};function i(r,a,c,p,o,u){return t(),s("div",null,[...a[0]||(a[0]=[l('<div id="第5部-c-の言語機能" class="study-legacy-anchor" aria-hidden="true"></div><h1 id="c-の言語機能を学ぶ" tabindex="-1">C++の言語機能を学ぶ <a class="header-anchor" href="#c-の言語機能を学ぶ" aria-label="Permalink to &quot;C++の言語機能を学ぶ&quot;">​</a></h1><p>C++の言語機能を「構文」ではなく「<strong>仕組みと目的</strong>」から説明する章です。各ページに必ず、<strong>C#との違い/Unity開発者が誤解しやすい点/ゲーム開発での使用例/メモリ上で起きること</strong>を含めています。</p><p>コード例は原則 <strong>C++20</strong> です(検証環境: MinGW GCC 9.2、C++20部分サポート。concepts/rangesの例は構文レビューのみ — 各ページに明記)。</p><h2 id="読む順番-前提の少ない順" tabindex="-1">読む順番(前提の少ない順) <a class="header-anchor" href="#読む順番-前提の少ない順" aria-label="Permalink to &quot;読む順番(前提の少ない順)&quot;">​</a></h2><ol><li><a href="/study/languages/cpp/values-pointers-references.html">値型と参照・ポインタ・参照</a> — <strong>最重要。C#との世界観の違いの核心</strong></li><li><a href="/study/languages/cpp/const-correctness.html">const と const correctness</a></li><li><a href="/study/languages/cpp/arrays-and-strings.html">配列と文字列</a></li><li><a href="/study/languages/cpp/structs-and-classes.html">構造体・クラス・アクセス指定子</a></li><li><a href="/study/languages/cpp/ctor-dtor-copy-move.html">コンストラクタ・デストラクタ・コピー・ムーブ(Rule of Zero/Three/Five)</a></li><li><a href="/study/languages/cpp/raii.html">RAII</a> — <strong>C++の設計思想の核</strong></li><li><a href="/study/languages/cpp/inheritance-and-virtual.html">継承・仮想関数・抽象クラス・override/final</a></li><li><a href="/study/languages/cpp/overloading.html">関数オーバーロードと演算子オーバーロード</a></li><li><a href="/study/languages/cpp/templates-and-concepts.html">テンプレートと concepts</a></li><li><a href="/study/languages/cpp/lambdas-and-functions.html">ラムダ式・関数ポインタ・std::function</a></li><li><a href="/study/languages/cpp/enums-and-namespaces.html">enum・enum class・namespace</a></li><li><a href="/study/languages/cpp/exceptions.html">例外</a></li><li><a href="/study/languages/cpp/auto-and-constexpr.html">auto・decltype・constexpr・consteval</a></li><li><a href="/study/languages/cpp/static-inline-friend.html">static・inline・friend</a></li><li><a href="/study/languages/cpp/casts.html">キャスト</a></li><li><a href="/study/languages/cpp/smart-pointers.html">スマートポインタ</a></li><li><a href="/study/languages/cpp/stl.html">STLコンテナ・イテレータ・アルゴリズム・ranges</a></li><li><a href="/study/languages/cpp/undefined-behavior.html">未定義動作・実装定義・未規定動作</a></li></ol><p>仕上げに <a href="/study/languages/cpp/exercises.html">演習</a>。</p><h2 id="c-経験者への注意-この章全体の前提" tabindex="-1">C#経験者への注意(この章全体の前提) <a class="header-anchor" href="#c-経験者への注意-この章全体の前提" aria-label="Permalink to &quot;C#経験者への注意(この章全体の前提)&quot;">​</a></h2><ul><li>C++には<strong>GCがない</strong>。誰がいつメモリを解放するか(所有権)を常にコードで表現する</li><li>C++の変数は既定で<strong>値</strong>(コピーされる実体)。C#のclassのような「参照の共有」はポインタ/参照で明示する</li><li>C++は「間違ったコードはコンパイルエラー」とは限らず、<strong>未定義動作</strong>として静かに壊れることがある(→ <a href="/study/languages/cpp/undefined-behavior.html">18</a>)</li></ul><hr><p><a href="/study/guide/cpp-index.html">全体目次</a> | 次: <a href="/study/languages/cpp/values-pointers-references.html">値型と参照・ポインタ・参照</a></p>',11)])])}const h=e(n,[["render",i]]);export{g as __pageData,h as default};
